"""Accessible full-map shell. The existing catalog owns all trip facts."""
from html import escape as E


def markup(records, styles, catalog):
    def options(values):
        return ''.join('<option value="'+E(v, quote=True)+'">'+E(v)+'</option>' for v in values)
    environments = sorted({e for r in records for e in r['environments']})
    species = sorted({s for r in records for s in r['species']})
    months = ['January','February','March','April','May','June','July','August','September','October','November','December']
    return '''<section class="atlas-explorer" data-atlas-gl data-catalog="'''+catalog+'''"><header class="atlas-heading"><div><span class="eyebrow">THE ATLAS / FIND YOUR WATER</span><h1>A world worth<br>casting into.</h1></div><p>Quiet rivers. Open oceans. Your next trip.<br>Choose a pin and follow the water.</p></header>
<form class="atlas-filters" role="search" aria-label="Filter trips"><div class="atlas-search"><label for="atlas-search">Search a place, trip or fish</label><div><input id="atlas-search" name="search" type="search" placeholder="Try Alaska, tarpon or Norway" autocomplete="off"><button type="submit">Find on map ↗</button></div></div>
<fieldset class="atlas-water"><legend>Water type</legend>'''+''.join('<button type="button" data-water="'+value+'" aria-pressed="'+('true' if not value else 'false')+'">'+label+'</button>' for value,label in [('', 'All waters'),('Freshwater','Freshwater'),('Saltwater','Saltwater'),('Ice','Ice'),('Brackish','Brackish')])+'''</fieldset>
<button class="atlas-refine" type="button" data-refine aria-expanded="false" aria-controls="atlas-extra-filters">Refine the results +</button><div class="atlas-selects" id="atlas-extra-filters"><label>Environment<select name="environment"><option value="">All environments</option>'''+options(environments)+'''</select></label><label>Species / target<select name="species"><option value="">All targets</option>'''+options(species)+'''</select></label><label>Month<select name="month"><option value="">Any month</option>'''+''.join('<option value="'+str(i)+'">'+m+'</option>' for i,m in enumerate(months,1))+'''</select></label><label>Trip style<select name="style"><option value="">All styles</option>'''+''.join('<option value="'+E(s['slug'])+'">'+E(s['name'])+'</option>' for s in styles)+'''</select></label></div></form>
<div class="atlas-action-row"><p class="atlas-result-count" role="status">'''+str(len(records))+''' trips</p><button type="button" class="atlas-view-toggle" data-view-toggle aria-pressed="false">List view</button><button type="button" data-clear>Clear filters</button><button type="button" data-fit>Fit to results</button><button type="button" data-near>◎ Near me</button><a href="#atlas-list">Browse the list ↓</a></div>
<p class="atlas-map-message" role="status">The map needs JavaScript and a network connection. All trips are in the list below.</p>
<div class="atlas-gl-stage"><button type="button" class="atlas-area-button" data-search-area hidden>Search this area ↗</button><div id="atlas-map" role="region" aria-label="Interactive fishing map. Use two fingers on touch screens. Use the list below for all trip links."></div><aside class="atlas-trip-panel" aria-label="Selected trip" hidden></aside><div class="atlas-legend"><span><i class="fresh"></i>Freshwater</span><span><i class="salt"></i>Saltwater</span><span><i class="ice"></i>Ice</span><span><i class="other"></i>Mixed / other</span></div></div>
<div class="atlas-mobile-sheet"><div class="atlas-sheet-handle" aria-hidden="true"></div><div class="atlas-sheet-heading"><strong>Follow your next good feeling.</strong><span data-sheet-count></span></div><div class="atlas-swipe-cards" aria-label="Trip cards. Swipe to explore." tabindex="0"></div></div><p class="atlas-map-note">Pins show approximate places, not launch sites. <a href="/media/atlas/locations.json">Location sources</a>.<br>Month filters use documented windows only. Missing months do not mean no fishing.</p>
<details class="atlas-trip-list" id="atlas-list" open><summary>Browse trips as a list</summary><div class="atlas-list-content"><ul>'''+''.join('<li><a href="'+E(r['path'],quote=True)+'">'+E(r['name'])+'</a><span>'+E(r['region'])+'</span></li>' for r in records)+'''</ul></div></details></section>'''
